import java.util.*;
class Solution {
    public boolean find132pattern(int[] nums) {
        Deque<Integer>st=new ArrayDeque<>();long third=Long.MIN_VALUE;
        for(int i=nums.length-1;i>=0;i--){if(nums[i]<third)return true;while(!st.isEmpty()&&nums[i]>st.peek())third=st.pop();st.push(nums[i]);}
        return false;
    }
}

class Solution {
    public boolean circularArrayLoop(int[] nums) {
        int n=nums.length;
        for(int start=0;start<n;start++){if(nums[start]==0)continue;int dir=nums[start]>0?1:-1,slow=start,fast=start;
            while(true){slow=next(nums,slow,dir);if(slow<0)break;fast=next(nums,fast,dir);if(fast<0)break;fast=next(nums,fast,dir);if(fast<0)break;if(slow==fast)return true;}
            int cur=start;while(nums[cur]*dir>0){int nx=((cur+nums[cur])%n+n)%n;nums[cur]=0;cur=nx;}
        }return false;
    }
    private int next(int[]a,int i,int dir){if(a[i]*dir<0)return -1;int j=((i+a[i])%a.length+a.length)%a.length;return j==i?-1:j;}
}

