class Solution:
    def islandPerimeter(self, grid: list[list[int]]) -> int:
        perimeter=0
        for r,row in enumerate(grid):
            for c,x in enumerate(row):
                if not x:continue
                perimeter+=4
                if r>0 and grid[r-1][c]:perimeter-=2
                if c>0 and grid[r][c-1]:perimeter-=2
        return perimeter

class Solution {
    public int islandPerimeter(int[][] grid) {
        int m=grid.length,n=grid[0].length,p=0;
        for(int r=0;r<m;r++)for(int c=0;c<n;c++)if(grid[r][c]==1){p+=4;if(r>0&&grid[r-1][c]==1)p-=2;if(c>0&&grid[r][c-1]==1)p-=2;}
        return p;
    }
}

from functools import lru_cache
class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        if desiredTotal<=0:return True
        if maxChoosableInteger*(maxChoosableInteger+1)//2<desiredTotal:return False
        @lru_cache(None)
        def win(mask,remaining):
            for x in range(1,maxChoosableInteger+1):
                bit=1<<(x-1)
                if not mask&bit and (x>=remaining or not win(mask|bit,remaining-x)):return True
            return False
        return win(0,desiredTotal)

import java.util.*;
class Solution {
    private Boolean[] memo;private int max;
    public boolean canIWin(int maxChoosableInteger,int desiredTotal) {
        if(desiredTotal<=0)return true;if((long)maxChoosableInteger*(maxChoosableInteger+1)/2<desiredTotal)return false;
        max=maxChoosableInteger;memo=new Boolean[1<<max];return win(0,desiredTotal);
    }
    private boolean win(int mask,int remain){if(memo[mask]!=null)return memo[mask];for(int x=1;x<=max;x++){int bit=1<<(x-1);if((mask&bit)==0&&(x>=remain||!win(mask|bit,remain-x)))return memo[mask]=true;}return memo[mask]=false;}
}

class Solution:
    def findSubstringInWraproundString(self, p: str) -> int:
        best=[0]*26;run=0
        for i,c in enumerate(p):
            if i and (ord(c)-ord(p[i-1]))%26==1:run+=1
            else:run=1
            idx=ord(c)-97;best[idx]=max(best[idx],run)
        return sum(best)

class Solution {
    public int findSubstringInWraproundString(String p) {
        int[]best=new int[26];int run=0;
        for(int i=0;i<p.length();i++){if(i>0&&(p.charAt(i)-p.charAt(i-1)+26)%26==1)run++;else run=1;int x=p.charAt(i)-'a';best[x]=Math.max(best[x],run);}
        int ans=0;for(int x:best)ans+=x;return ans;
    }
}

class Solution:
    def validIPAddress(self, queryIP: str) -> str:
        if queryIP.count('.')==3:
            parts=queryIP.split('.')
            if len(parts)!=4:return "Neither"
            for x in parts:
                if not x or not x.isdigit() or (len(x)>1 and x[0]=='0') or int(x)>255:return "Neither"
            return "IPv4"
        if queryIP.count(':')==7:
            parts=queryIP.split(':')
            if len(parts)!=8:return "Neither"
            for x in parts:
                if not 1<=len(x)<=4 or any(c not in "0123456789abcdefABCDEF" for c in x):return "Neither"
            return "IPv6"
        return "Neither"

class Solution {
    public String validIPAddress(String queryIP) {
        if(queryIP.chars().filter(c->c=='.').count()==3){
            String[]p=queryIP.split("\\.",-1);if(p.length!=4)return "Neither";
            for(String x:p){if(x.isEmpty()||(x.length()>1&&x.charAt(0)=='0'))return "Neither";int v=0;for(char c:x.toCharArray()){if(c<'0'||c>'9')return "Neither";v=v*10+c-'0';}if(v>255)return "Neither";}return "IPv4";
        }
        if(queryIP.chars().filter(c->c==':').count()==7){
            String[]p=queryIP.split(":",-1);if(p.length!=8)return "Neither";
            for(String x:p){if(x.length()<1||x.length()>4)return "Neither";for(char c:x.toCharArray())if(!((c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F')))return "Neither";}return "IPv6";
        }return "Neither";
    }
}
